import { Injectable } from '@angular/core';
import { CanActivate } from '@angular/router';

// ❌ OLD: A class guard must be declared, provided, and wired into the
// route with its class name. Constructor DI is verbose and the guard
// cannot be expressed as a lightweight function.
@Injectable({ providedIn: 'root' })
export class AuthGuard implements CanActivate {
  constructor(private auth: AuthService) {} // ❌ OLD: constructor plumbing

  canActivate() {
    return this.auth.isLoggedIn();
  }
}

// Route wiring: { path: 'admin', canActivate: [AuthGuard] }

import { inject } from '@angular/core';
import { CanActivateFn } from '@angular/router';

// ✅ NEW: A plain function can call inject() because guards run inside
// an injection context. No class, no constructor, no @Injectable.
export const authGuard: CanActivateFn = () => {
  const auth = inject(AuthService); // ✅ NEW: resolves from the current injector
  return auth.isLoggedIn();
};

// Route wiring: { path: 'admin', canActivate: [authGuard] }

// inject() also works in field initializers and provider factories:
